#!/usr/bin/env python3
"""payload.py -- writes a C file that holds files as byte arrays, for lcc-run.

Usage: payload.py output.c name=path [name=path ...]

Each name is the path the file gets when lcc-run unpacks it, for example
bin/q3asm or include/stdio.h. The arrays are read-only data of the executable.
"""
import sys


def main(argv):
    out = argv[1]
    entries = []
    for pair in argv[2:]:
        name, path = pair.split("=", 1)
        with open(path, "rb") as f:
            entries.append((name, f.read()))

    lines = [
        "/* payload.c -- generated by payload.py, do not edit */",
        "#include <stddef.h>",
        '#include "payload.h"',
        "",
    ]
    for i, (name, data) in enumerate(entries):
        lines.append("static const unsigned char file%d[] = {" % i)
        for j in range(0, len(data), 16):
            chunk = data[j:j + 16]
            lines.append("    " + ", ".join("0x%02x" % b for b in chunk) + ",")
        if not data:
            lines.append("    0")
        lines.append("};")
        lines.append("")
    lines.append("const struct payload_file payload_files[] = {")
    for i, (name, data) in enumerate(entries):
        lines.append('    { "%s", file%d, %d },' % (name, i, len(data)))
    lines.append("    { NULL, NULL, 0 }")
    lines.append("};")
    lines.append("")
    with open(out, "w") as f:
        f.write("\n".join(lines))
    print("packed %d files into %s" % (len(entries), out))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
